package productstate

import (
	"context"
	"encoding/json"
	"fmt"
	"sync"
	"testing"
	"time"
)

func xpayload(tag string, n int) []byte {
	b, _ := json.Marshal(map[string]any{"tag": tag, "n": n})
	return b
}

// X3: Load runs header and item queries as separate autocommit statements;
// a concurrent Save committing between them yields a hybrid record.
func TestX3TornReadUnderConcurrentSave(t *testing.T) {
	root := t.TempDir()
	store, err := Ensure(root)
	if err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()

	stop := make(chan struct{})
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; ; i++ {
			select {
			case <-stop:
				return
			default:
			}
			tag, n := "A", 1
			if i%2 == 1 {
				tag, n = "B", 2
			}
			rec := Record{Kind: "study_run", Scope: "s", SchemaVersion: 1,
				Header: xpayload(tag, n),
				Items:  []Item{{Key: "t1", Ordinal: 0, Payload: xpayload(tag, n)}}}
			if n == 2 {
				rec.Items = append(rec.Items, Item{Key: "t2", Ordinal: 1, Payload: xpayload(tag, n)})
			}
			if err := store.Save(ctx, rec); err != nil {
				t.Errorf("save: %v", err)
				return
			}
		}
	}()

	torn := 0
	var example error
	reads := 0
	deadline := time.Now().Add(15 * time.Second)
	for time.Now().Before(deadline) && reads < 20000 {
		rec, err := store.Load(ctx, "study_run", "s")
		if err != nil {
			if ErrNotFound == err {
				continue
			}
			example = err
			break
		}
		if len(rec.Items) == 0 {
			continue
		}
		reads++
		var h struct {
			Tag string `json:"tag"`
			N   int    `json:"n"`
		}
		_ = json.Unmarshal(rec.Header, &h)
		mixed := len(rec.Items) != h.N
		for _, it := range rec.Items {
			var p struct {
				Tag string `json:"tag"`
			}
			_ = json.Unmarshal(it.Payload, &p)
			if p.Tag != h.Tag {
				mixed = true
			}
		}
		if mixed {
			torn++
			if torn == 1 {
				itemTags := ""
				for _, it := range rec.Items {
					var p struct {
						Tag string `json:"tag"`
					}
					_ = json.Unmarshal(it.Payload, &p)
					itemTags += p.Tag
				}
				t.Logf("X3 first torn record: header_tag=%s header_n=%d items=%d item_tags=%s", mustTag(rec.Header), h.N, len(rec.Items), itemTags)
			}
		}
	}
	close(stop)
	wg.Wait()
	t.Logf("X3 RESULT: reads=%d torn=%d lastErr=%v", reads, torn, example)
	if torn > 0 {
		t.Logf("X3 VERDICT: hybrid header/items records observed %d times (fmt %s)", torn, fmt.Sprint(""))
	}
}

func mustTag(b []byte) string {
	var s struct {
		Tag string `json:"tag"`
	}
	_ = json.Unmarshal(b, &s)
	return s.Tag
}
